'use strict';
const fs = require('fs');
const SP = '/tmp/claude-0/-home-user-ainews/e93426a8-d9ce-5159-9914-90a569d2972d/scratchpad';
const J = (f) => JSON.parse(fs.readFileSync(SP + '/' + f, 'utf8'));
const W = (f, o) => fs.writeFileSync(SP + '/' + f, JSON.stringify(o, null, 1) + '\n');

W('wk_h2.json', J('wk_h2.json').filter((x) => x.id !== 'anthropic-mythos-github'));
W('wk_h3.json', J('wk_h3.json').filter((x) => x.id !== 'anthropic-agents-on-government-sites'));

const h5 = J('wk_h5.json')
  .filter((x) => x.id !== 'openai-in-state-courts')
  .map((it) => {
    if (it.id === 'pentagon-autonomous-warfare-command') {
      it.bullets = it.bullets.map((b) =>
        b.replace(/and that neutralising a target could mean/, 'and described neutralising a target as')
      );
    }
    return it;
  });
W('wk_h5.json', h5);

const c = J('wk_c.json').map((x) => {
  if (x.id === 'both-labs-published-their-own-failures') {
    x.items = ['openai-containment', 'anthropic-agents-outside-authorisation'];
    x.explanation = x.explanation.map((p) =>
      p.replace(/primary document could be read in full/, 'primary document was readable in full')
    );
  }
  if (x.id === 'the-same-model-families-on-both-sides') {
    x.explanation = x.explanation.map((p) =>
      p.replace(/ It isn.t a Log4J moment\./, '')
    );
  }
  return x;
});
W('wk_c.json', c);

// unknowns: relates_to pointing at the merged/removed ids
const u = J('wk_u.json');
u.unknowns = u.unknowns.map((q) => {
  q.relates_to = q.relates_to.map((r) =>
    r === 'anthropic-mythos-github' || r === 'anthropic-agents-on-government-sites'
      ? 'anthropic-agents-outside-authorisation'
      : r
  );
  q.relates_to = [...new Set(q.relates_to)];
  return q;
});
W('wk_u.json', u);
console.log('done');

