'use strict';
const fs = require('fs');
const wk = JSON.parse(fs.readFileSync('/home/user/ainews/data/2026-10-26.week.json', 'utf8'));
const days = ['2026-10-19','2026-10-20','2026-10-21','2026-10-22','2026-10-23','2026-10-24','2026-10-25','2026-10-26'];
const edUrls = {};
for (const d of days) {
  const ed = JSON.parse(fs.readFileSync('/home/user/ainews/data/' + d + '.json', 'utf8'));
  edUrls[d] = new Set(ed.sections.flatMap((s) => (s.items || []).flatMap((it) => (it.sources || []).map((x) => x.url))));
}
for (const it of wk.happened) {
  const match = days.filter((d) => it.sources.some((s) => edUrls[d].has(s.url)));
  console.log(it.id, '| declared:', it.editions.join(','), '| matching:', match.join(','));
}
console.log('--- HEDGES ---');
const HED = /\b(likely|could|might|should|must|notably|importantly|striking|remarkable|unprecedented|historic|landmark)\b/i;
const strip = (t) => String(t).replace(/"[^"]*"|“[^”]*”/g, ' ');
for (const it of wk.happened) {
  it.bullets.forEach((b, i) => {
    const s = strip(b);
    const m = s.match(HED);
    if (m) {
      const idx = s.indexOf(m[0]);
      console.log(it.id, 'bullet', i, '::', m[0], '::', s.slice(Math.max(0, idx - 90), idx + 70).replace(/\s+/g, ' '));
    }
  });
}

