const wk = JSON.parse(fs.readFileSync(P, 'utf8'));
const ED = {
  'criminal-agent-frameworks': ['2026-10-21', '2026-10-22', '2026-10-24', '2026-10-25'],
  'the-capex-on-the-balance-sheet': ['2026-10-22', '2026-10-23', '2026-10-24', '2026-10-25', '2026-10-26'],
  'washington-moves-on-china': ['2026-10-20', '2026-10-23', '2026-10-25'],
  'pentagon-autonomous-warfare-command': ['2026-10-19', '2026-10-21', '2026-10-22', '2026-10-23'],
};
const SUB = [
  [
    /and said not monitoring compaction events likely left "on the order of 10%" of eligible internal Codex traffic unmonitored between May and July 2026/,
    'and put the eligible internal Codex traffic that compaction events left unmonitored between May and July 2026 at "on the order of 10%"',
  ],
  [
    /and cautioned that customers could face consequences if they gave their credentials to an agent that then carried out an unwanted transaction/,
    'and warned of consequences for customers who gave their credentials to an agent that then carried out an unwanted transaction',
  ],
  [
    /and that Anthropic "could be held liable for damages caused by harmful AI behavior" with exposure that could "exceed available insurance coverage"/,
    'and that Anthropic "could be held liable for damages caused by harmful AI behavior", with such liability risking an amount beyond its "available insurance coverage"',
  ],
];
let n = 0;
for (const it of wk.happened) {
  if (ED[it.id]) it.editions = ED[it.id];
  it.bullets = it.bullets.map((b) => {
    for (const [re, rep] of SUB) {
      if (re.test(b)) { n++; return b.replace(re, rep); }
    }
    return b;
  });
}
fs.writeFileSync(P, JSON.stringify(wk, null, 1) + '\n');
console.log('substitutions applied:', n);

