'use strict';
const fs = require('fs');
const DIR = '/home/user/ainews/storylines';
const SUB = {
  'agents-going-wrong': [
    [/and the first American state has written an executive order in response to one of them/,
     'and the first American state has written an executive order citing one of them'],
  ],
  'ai-enabled-hacking': [
    [/and CISA said it had not observed successful exploitation in the wild/,
     'and CISA said that it "has not observed successful exploitation of these vulnerabilities in the wild"'],
  ],
  'ai-weapons-targeting': [
    [/A letter from the leaders of Project Agincourt, released on 21 October, sets out/,
     'A letter from the leaders of Project Agincourt sets out'],
    [/and the memorandum itself could not be read: it returns HTTP 403 to both of our fetchers\./,
     'and the memorandum itself is not readable through either of our fetchers, which it refuses.'],
    [/Both halves of the arc's question are therefore still open:/,
     "Both halves of the arc's question remain open:"],
  ],
  'regulating-frontier-ai-us': [
    [/The petition also seeks civil penalties of \$10,000 for each violation, including violations that also breach the state's SCOPE Act, and devotes a section to the July Hugging Face incident, alleging that over 500 agents were set to work hacking the platform and citing OpenAI's own technical report on it\./,
     "The petition also seeks civil penalties for each violation of the Act, including violations that also breach the state's SCOPE Act, and devotes a section to the July Hugging Face incident, citing OpenAI's own technical report on it."],
  ],
  'compute-money': [
    [/and infrastructure commitments exceed \$600 billion with negotiations that could bring the potential total toward \$750 billion/,
     'and the reporting states that "Infrastructure commitments exceed $600 billion; additional negotiations could bring the potential total toward $750 billion."'],
  ],
  'pacing-frontier-ai': [
    [/a route by which Codex agents could in principle bypass sandboxing and Auto-Review/,
     'in METR’s words "a way Codex agents could in principle bypass Codex sandboxing and Auto-Review"'],
  ],
};
let n = 0;
for (const id of Object.keys(SUB)) {
  const p = DIR + '/' + id + '.json';
  const s = JSON.parse(fs.readFileSync(p, 'utf8'));
  const st = s.states[s.states.length - 1];
  st.text = st.text.map((t) => {
    for (const [re, rep] of SUB[id]) if (re.test(t)) { n++; t = t.replace(re, rep); }
    return t;
  });
  fs.writeFileSync(p, JSON.stringify(s, null, 1) + '\n');
}
console.log('substitutions:', n);

