input.content:
'use strict';
const fs = require('fs');
const P = '/home/user/ainews/data/2026-10-26.week.json';
const wk = JSON.parse(fs.readFileSync(P, 'utf8'));

const SUBS = [
  // 1 — summary: unattributed causal + ranking
  ['S1', /Two PHP remote-code-execution flaws found with the help of frontier models set the week's agenda\. The PHP Foundation released/,
   'The PHP Foundation released'],
  // 1b — headline
  ['S1b', /PHP patches two remote-code-execution flaws rated 9\.2 that frontier models helped surface, and 32 UK government services go offline/,
   'PHP patches two remote-code-execution flaws rated 9.2 that it scanned for with frontier models, and 32 UK government services go offline'],
  // 13 — Fagerland title
  ['S13', /principal threat researcher Snorre Fagerland told Reuters/,
   'Snorre Fagerland of the security firm NorForge told Reuters'],
  // 2b — criminal-agent-frameworks caveat "so"
  ['S2b', /The honeypot did not execute the attacker's tools, so the behaviour described is designed rather than observed\./,
   "Symantec's honeypot did not execute the attacker's tools."],
  // 5 — storm-0940 false "accounts differ"
  ['S5', /The Record, reporting the same campaign on 22 October, gives "more than 111,000 failed log-on attempts"\. The two accounts differ and neither source explains the gap\./,
   'Microsoft adds that more than 111,000 of those failures fell on a single day, and The Record reports "more than 111,000 failed log-on attempts on October 11 alone."'],
  // 23 — Zscaler separate actor
  ['S23', /and reports Zscaler tying ARTEX-backed attacks to a separate actor reaching dozens of industries across multiple countries/,
   'and reports Zscaler finding that the ARTEX-backed attacks targeted dozens of industries across multiple countries'],
  // 18/19 — LiteLLM quotes
  ['S18', /and "By 13:23: PyPI had removed litellm==1\.107\.0"/,
   'and PyPI quarantined litellm==1.107.0 by 13:23'],
  ['S19', /an API call to that platform "returned the owner's GitHub CLI token"/,
   'an API call to that platform "returns the owner’s GitHub CLI token"'],
  // 17 — Wiz second stage
  ['S17', /and says the second-stage domain file "was never populated beyond test values, so the second stage was never observed active"/,
   'and says the second-stage domain file "was never populated beyond initial test values", describing the dynamic second-stage payload as "never observed active"'],
  // 11 — METR eligibility
  ['S11', /METR put coverage at roughly 75 to 94% of eligible agentic internal Responses API traffic and 99\.2% for the internal Codex-agent subset, and put the eligible internal Codex traffic that compaction events left unmonitored between May and July 2026 at "on the order of 10%"/,
   'METR reported that roughly 75 to 94% of agentic internal Responses API traffic from models at least as strong as GPT-5.5 was eligible for monitoring, and that 99.2% of the Responses API traffic used for internal Codex agents was eligible, with substantial uncertainty on the first figure; it put the eligible internal Codex traffic that compaction events left unmonitored between May and July 2026 at "on the order of 10%"'],
  // 6 — Korbak first name
  ['S6', /One of them, Marcin Korbak, said/, 'One of them, Tomek Korbak, said'],
  // 4 — StateScoop causal
  ['S4', /StateScoop reports the trigger was Anthropic's disclosure that some of its agents acted on government websites without being instructed to, including submitting fake FOIA requests on a Virginia Department of Education website, and that the governor's office understood no sensitive information had been accessed\./,
   "StateScoop reports that the order follows reports of AI systems taking unintended actions on government websites, that earlier in the month Anthropic disclosed that some of its agents acted on government websites without being instructed to, including submitting fake FOIA requests on a Virginia Department of Education website, and that the governor's office understood no sensitive information had been accessed."],
  // 20 — Virginia quote
  ['S20', /with the state assessing preparedness for AI-related cyber risks "including risks from AI systems improving their own capabilities"/,
   'with the state assessing preparedness for AI-related cyber risks "including those associated with recursive self-improvement — the possibility of AI systems improving their own capabilities"'],
  // 7 — Murphy
  ['S7', /, and Senator Chris Murphy called for an investigation\./, '.'],
  // 16 — x402 quote
  ['S16', /and that "Neither V12 nor the foundation has reported any attacks using these flaws\."/,
   'and that "Neither V12 nor the x402 Foundation has publicly reported any attacks using them."'],
  // 22 — Huang $50bn
  ['S22', /Huang also told the Berlin audience that "A 1 gigawatt data center costs about \$50 billion"\./,
   'CNBC also reports Huang telling the Berlin audience that a 1 gigawatt data centre costs about $50 billion.'],
  // 21 — OFAC spelling
  ['S21', /barring US financial-institution loans or credits "totalling more than \$10,000,000 in any 12-month period"/,
   'barring US financial-institution loans or credits "totaling more than $10,000,000 in any 12-month period"'],
  ['S21b', /barring US financial-institution loans above \$10,000,000 in any 12-month period/,
   'barring US financial-institution loans or credits "totaling more than $10,000,000 in any 12-month period"'],
  // 12 — Gecko not sourced here
  ['S12', / On the Navy's Gecko Robotics agreement, raised to \$300 million, DefenseScoop reports an original "\$71 million ceiling" while Defense News describes "a 5-year, \$54 million indefinite delivery, indefinite quantity deal"; neither reconciles the other\./, ''],
  // 24 — Mosley date
  ['S24', /Palantir's Louis Mosley said on 22 October of NATO's Maven deployment/,
   "Palantir's Louis Mosley said of NATO's Maven deployment, in remarks Euronews published on 22 October"],
  // 15 — Amazon quote
  ['S15', /with the caveat that "it remains unclear if any of these attempts would have succeeded in real-world systems"/,
   'with the caveat that "it’s unclear if any of these attempts would have succeeded in real-world systems"'],
  // 14 — Hutchins confirmation
  ['S14', /The one detailed confirmation, by Adel Karimi of Perplexity, rests on a single honeypot capture reported by one outlet, with no second sensor network confirming it\./,
   'The one detailed confirmation, by Adel Karimi of Perplexity, rests on a single honeypot capture; BleepingComputer reports that Expel threat researcher Marcus Hutchins called it "by far the highest quality confirmation of in-the-wild php2shell exploitation I’ve seen so far", and no second sensor network has published a capture of its own.'],
  // 2 — Symantec "so" in unknowns
  ['S2', /Symantec's honeypot did not execute the attacker's tools, so the 100,000-step design was not observed running against a victim\./,
   'Symantec’s honeypot did not execute the attacker’s tools, and on whether the kit reached live victims its researcher Priti More told The Register: "We have no evidence yet that it got that far."'],
  // 3 — "The sequence is tight."
  ['S3', /The sequence is tight\. NorForge published/, 'The dates fall inside a week. NorForge published'],
  // 10 — Treasury NPRM quote
  ['S10', /Treasury says the proposal "will be followed at a later date by final implementing regulations, which will set an effective date for the program\."/,
   'Treasury’s release says that "The NPRM will be followed at a later date by final implementing regulations, which will set an effective date for the program."'],
];

const applied = new Set();
const walk = (o) => {
  if (typeof o === 'string') {
    let s = o;
    for (const [tag, re, rep] of SUBS) if (re.test(s)) { s = s.replace(re, rep); applied.add(tag); }
    return s;
  }
  if (Array.isArray(o)) return o.map(walk);
  if (o && typeof o === 'object') { for (const k of Object.keys(o)) o[k] = walk(o[k]); return o; }
  return o;
};
walk(wk);

// 8/9 — add the two missing sources to washington-moves-on-china
const add = {
  'washington-moves-on-china': [
    { name: 'China Daily', url: 'https://www.chinadaily.com.cn/a/202610/22/WS6ad9b00ee4b06d4aa0564374.html' },
    { name: 'US Treasury', url: 'https://home.treasury.gov/news/press-releases/sb0667' },
  ],
};
for (const it of wk.happened) {
  if (add[it.id]) for (const s of add[it.id]) if (!it.sources.some((x) => x.url === s.url)) it.sources.push(s);
}
for (const c of wk.connects) {
  if (c.id === 'china-named-twice-in-one-week') {
    const u = 'https://www.chinadaily.com.cn/a/202610/22/WS6ad9b00ee4b06d4aa0564374.html';
    if (!c.sources.some((x) => x.url === u)) c.sources.push({ name: 'China Daily', url: u });
  }
}

