   'barring US financial-institution loans or credits "totaling more than $10,000,000 in any 12-month period"'],
  ['S21b', /barring US financial-institution loans above \$10,000,000 in any 12-month period/,
   'barring US financial-institution loans or credits "totaling more than $10,000,000 in any 12-month period"'],
  // 12 — Gecko not sourced here
  ['S12', / On the Navy's Gecko Robotics agreement, raised to \$300 million, DefenseScoop reports an original "\$71 million ceiling" while Defense News describes "a 5-year, \$54 million indefinite delivery, indefinite quantity deal"; neither reconciles the other\./, ''],
  // 24 — Mosley date
  ['S24', /Palantir's Louis Mosley said on 22 October of NATO's Maven deployment/,
   "Palantir's Louis Mosley said of NATO's Maven deployment, in remarks Euronews published on 22 October"],
  // 15 — Amazon quote
  ['S15', /with the caveat that "it remains unclear if any of these attempts would have succeeded in real-world systems"/,
   'with the caveat that "it\u2019s unclear if any of these attempts would have succeeded in real-world systems"'],
  // 14 — Hutchins confirmation
  ['S14', /The one detailed confirmation, by Adel Karimi of Perplexity, rests on a single honeypot capture reported by one outlet, with no second sensor network confirming it\./,
   'The one detailed confirmation, by Adel Karimi of Perplexity, rests on a single honeypot capture; BleepingComputer reports that Expel threat researcher Marcus Hutchins called it "by far the highest quality confirmation of in-the-wild php2shell exploitation I\u2019ve seen so far", and no second sensor network has published a capture of its own.'],
  // 2 — Symantec "so" in unknowns
  ['S2', /Symantec's honeypot did not execute the attacker's tools, so the 100,000-step design was not observed running against a victim\./,
   'Symantec\u2019s honeypot did not execute the attacker\u2019s tools, and on whether the kit reached live victims its researcher Priti More told The Register: "We have no evidence yet that it got that far."'],
  // 3 — "The sequence is tight."
  ['S3', /The sequence is tight\. NorForge published/, 'The dates fall inside a week. NorForge published'],
  // 10 — Treasury NPRM quote
  ['S10', /Treasury says the proposal "will be followed at a later date by final implementing regulations, which will set an effective date for the program\."/,
   'Treasury\u2019s release says that "The NPRM will be followed at a later date by final implementing regulations, which will set an effective date for the program."'],
];

const applied = new Set();
const walk = (o) => {
  if (typeof o === 'string') {
    let s = o;
    for (const [tag, re, rep] of SUBS) if (re.test(s)) { s = s.replace(re, rep); applied.add(tag); }
    return s;
  }
  if (Array.isArray(o)) return o.map(walk);
  if (o && typeof o === 'object') { for (const k of Object.keys(o)) o[k] = walk(o[k]); return o; }
  return o;
};
walk(wk);

// 8/9 — add the two missing sources to washington-moves-on-china
const add = {
  'washington-moves-on-china': [
    { name: 'China Daily', url: 'https://www.chinadaily.com.cn/a/202610/22/WS6ad9b00ee4b06d4aa0564374.html' },
    { name: 'US Treasury', url: 'https://home.treasury.gov/news/press-releases/sb0667' },
  ],
};
for (const it of wk.happened) {
  if (add[it.id]) for (const s of add[it.id]) if (!it.sources.some((x) => x.url === s.url)) it.sources.push(s);
}
for (const c of wk.connects) {
  if (c.id === 'china-named-twice-in-one-week') {
    const u = 'https://www.chinadaily.com.cn/a/202610/22/WS6ad9b00ee4b06d4aa0564374.html';
    if (!c.sources.some((x) => x.url === u)) c.sources.push({ name: 'China Daily', url: u });
  }
}

fs.writeFileSync(P, JSON.stringify(wk, null, 1) + '\n');
console.log('applied:', [...applied].join(' '));
console.log('NOT applied:', SUBS.map((s) => s[0]).filter((t) => !applied.has(t)).join(' ') || 'none');

